224: func parseEvents(raw []byte) (text string, tokens Tokens, cost float64, sessionID string, toolCalls, eventCount int) {
225: 	scanner := bufio.NewScanner(bytes.NewReader(raw))
226: 	scanner.Buffer(make([]byte, 1024*1024), 16*1024*1024)
227: 	var builder strings.Builder
228: 	var accumulated Tokens
229: 	var accumulatedCost float64
230: 	for scanner.Scan() {
231: 		line := bytes.TrimSpace(scanner.Bytes())
232: 		if len(line) == 0 {
233: 			continue
234: 		}
235: 		var item event
236: 		if err := json.Unmarshal(line, &item); err != nil {
237: 			continue
238: 		}
239: 		eventCount++
240: 		if item.SessionID != "" {
241: 			sessionID = item.SessionID
242: 		}
243: 		var part map[string]json.RawMessage
244: 		if err := json.Unmarshal(item.Part, &part); err != nil {
245: 			continue
246: 		}
247: 		if typeRaw, ok := part["type"]; ok {
248: 			var partType string
249: 			_ = json.Unmarshal(typeRaw, &partType)
250: 			if strings.HasPrefix(partType, "tool") {
251: 				toolCalls++
252: 			}
253: 		}
254: 		if item.Type == "text" {
255: 			if textRaw, ok := part["text"]; ok {
256: 				var chunk string
257: 				if json.Unmarshal(textRaw, &chunk) == nil {
258: 					builder.WriteString(chunk)
259: 				}
260: 			}
261: 		}
262: 		if item.Type == "step_finish" {
263: 			var finish finishPart
264: 			if json.Unmarshal(item.Part, &finish) == nil {
265: 				accumulated.Input += finish.Tokens.Input
266: 				accumulated.Output += finish.Tokens.Output
267: 				accumulated.Reasoning += finish.Tokens.Reasoning
268: 				accumulated.CacheRead += finish.Tokens.Cache.Read
269: 				accumulated.CacheWrite += finish.Tokens.Cache.Write
270: 				accumulatedCost += finish.Cost
271: 			}
272: 		}
273: 	}
274: 	return builder.String(), accumulated, accumulatedCost, sessionID, toolCalls, eventCount
275: }
276: 
277: // ApplyEvents reparses a raw event stream into a record. Used to recompute
278: // token aggregates after parser fixes without re-running model calls.
279: func ApplyEvents(record *RunRecord, raw []byte) {
280: 	text, tokens, cost, sessionID, toolCalls, eventCount := parseEvents(raw)
281: 	record.Text = text
282: 	record.Tokens = tokens
283: 	record.Cost = cost
284: 	record.SessionID = sessionID
285: 	record.ToolCalls = toolCalls
286: 	record.EventCount = eventCount
287: 	record.Success = text != "" && record.ExitCode == 0
288: }
289: 
290: // VerifyTask runs the task verification command inside the isolated workspace.
291: func VerifyTask(record *RunRecord, task Task, timeout time.Duration) error {
292: 	if task.VerifyCommand == "" || record.WorkDir == "" {
293: 		return nil
294: 	}
295: 	if timeout <= 0 {
296: 		timeout = 2 * time.Minute
297: 	}
298: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
299: 	defer cancel()
300: 	parts := strings.Fields(task.VerifyCommand)
301: 	if len(parts) == 0 {
302: 		return nil
303: 	}
304: 	cmd := exec.CommandContext(ctx, parts[0], parts[1:]...)
305: 	cmd.Dir = record.WorkDir
306: 	output, err := cmd.CombinedOutput()
307: 	record.VerifyOutput = string(output)
308: 	if exitError, ok := err.(*exec.ExitError); ok {
309: 		record.VerifyExitCode = exitError.ExitCode()
310: 	} else if err != nil {
311: 		record.VerifyExitCode = -1
312: 	}
313: 	record.VerifyPassed = err == nil
314: 	return nil
315: }
316: 
317: // ScoreCompliance evaluates the machine-checkable applicable rules in a workspace.
318: func ScoreCompliance(record *RunRecord, task Task) {
319: 	result := Compliance{Applicable: len(task.ApplicableRules), Violated: []string{}}
320: 	machineRules := map[string]bool{"R001": true, "R002": true, "R003": true}
321: 	for _, rule := range task.ApplicableRules {
322: 		if !machineRules[rule] {
323: 			continue
324: 		}
325: 		result.Checked++
326: 		passed := false
327: 		switch rule {
328: 		case "R001":
329: 			passed = !workspaceContainsDash(record.WorkDir)
330: 		case "R002":
331: 			passed = !workspaceHasLargeFile(record.WorkDir)
332: 		case "R003":
333: 			passed = record.VerifyPassed
334: 		}
335: 		if passed {
336: 			result.Followed++
337: 		} else {
338: 			result.Violated = append(result.Violated, rule)
339: 		}
340: 	}
341: 	if result.Checked > 0 {
342: 		result.Pct = float64(result.Followed) / float64(result.Checked) * 100
343: 	}
344: 	record.Compliance = result
345: }
346: 
347: func workspaceContainsDash(root string) bool {
348: 	found := false
349: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
350: 		if err != nil || entry.IsDir() {
351: 			return nil
352: 		}
353: 		data, err := os.ReadFile(path)
354: 		if err != nil || len(data) > 1<<20 {
355: 			return nil
356: 		}
357: 		if strings.Contains(string(data), "\u2014") {
358: 			found = true
359: 		}
360: 		return nil
361: 	})
362: 	return found
363: }
364: 
365: func workspaceHasLargeFile(root string) bool {
366: 	found := false
367: 	_ = filepath.WalkDir(root, func(path string, entry os.DirEntry, err error) error {
368: 		if err != nil || entry.IsDir() {
369: 			return nil
370: 		}
371: 		data, err := os.ReadFile(path)
372: 		if err != nil || len(data) > 1<<20 {
373: 			return nil
374: 		}
375: 		if strings.Count(string(data), "\n")+1 > 700 {
376: 			found = true
377: 		}
378: 		return nil
379: 	})
380: 	return found
381: }
382: 
383: // prepareWorkspace creates an isolated directory and writes the task baseline into it.
384: func prepareWorkspace(root, id string, task Task) (string, error) {
385: 	dir := filepath.Join(root, id)
386: 	if err := os.MkdirAll(dir, 0o755); err != nil {
387: 		return "", err
388: 	}
389: 	names := make([]string, 0, len(task.Files))
390: 	for name := range task.Files {
391: 		names = append(names, name)
392: 	}
393: 	sort.Strings(names)
394: 	for _, name := range names {
395: 		path := filepath.Join(dir, name)
396: 		if err := os.MkdirAll(filepath.Dir(path), 0o755); err != nil {
397: 			return "", err
398: 		}
399: 		if err := os.WriteFile(path, []byte(task.Files[name]), 0o644); err != nil {
400: 			return "", err
401: 		}
402: 	}
403: 	return dir, nil
404: }
405: 
406: // RunOne executes a single task and persists its record. Completed successful runs are skipped.
407: func RunOne(request Request) (RunRecord, error) {
408: 	if err := os.MkdirAll(request.OutputDir, 0o755); err != nil {
409: 		return RunRecord{}, err
410: 	}
411: 	id := fmt.Sprintf("%s__%s__%s__%s", request.Condition, request.Task.ID, sanitize(request.Model.ID), request.Format)
412: 	recordPath := filepath.Join(request.OutputDir, id+".json")
413: 	if existing, err := os.ReadFile(recordPath); err == nil {
414: 		var record RunRecord
415: 		if json.Unmarshal(existing, &record) == nil && record.Success {
416: 			return record, nil
417: 		}
418: 	}
419: 
420: 	workDir, err := prepareWorkspace(request.WorkspaceRoot, id, request.Task)
421: 	if err != nil {
422: 		return RunRecord{}, err
423: 	}
424: 	binary := request.OpenCodeBinary
425: 	if binary == "" {
426: 		binary = "opencode"
427: 	}
428: 	prompt := request.Instruction + "\n\n--- TASK ---\n\n" + request.Task.Prompt
429: 
430: 	timeout := request.Timeout
431: 	if timeout <= 0 {
432: 		timeout = 10 * time.Minute
433: 	}
434: 	ctx, cancel := context.WithTimeout(context.Background(), timeout)
435: 	defer cancel()
436: 
437: 	args := []string{
438: 		"run",
439: 		"--model", request.Model.ID,
440: 		"--format", "json",
441: 		"--auto",
442: 		"--archived",
443: 		"--title", "ail-bench-"+id,
444: 		prompt,
445: 	}
446: 	cmd := exec.CommandContext(ctx, binary, args...)
447: 	cmd.Dir = workDir
